\title{Split Geometry: A Direction-Dependent Parallel Postulate on the Plane}
\author{Aristotle}
\date{\today}

\begin{document}

\begin{abstract}
We introduce and rigorously analyze \emph{Split Geometry}, a Riemannian structure on $\R^2$ whose infinitesimal length element expands in one coordinate direction and contracts in the perpendicular one:
\[ ds^2 = \frac{dx^2}{\cosh^2 y} + \cosh^2 x \, dy^2 . \]
The construction is designed so that the geometry behaves hyperbolically in some regions of the plane and elliptically in others, separated by a \emph{phase boundary}. We prove that the metric is positive-definite everywhere, hence a consistent Riemannian metric. We establish the exact monotonicity of $\sech^2 t = 1/\cosh^2 t$ in $|t|$ and use it to prove that the sign-indicator curvature $K(x,y)=\sech^2 x - \sech^2 y$ vanishes precisely on the diagonals $y=\pm x$, is positive where $|x|<|y|$, and is negative where $|y|<|x|$. We prove that any straight coordinate line not parallel to a diagonal meets the phase boundary in at most two points. We close with an honest comparison between the sign-indicator and the metric's true Gaussian curvature, a study of the split-triangle area functional, and future directions.
\end{abstract}

\maketitle

\section{Introduction}

The classification of two-dimensional geometries by the sign of curvature is a crown jewel of nineteenth-century mathematics. Euclid's parallel postulate corresponds to zero curvature and flat geometry. Its negation admits two consistent alternatives of constant curvature: hyperbolic geometry ($K<0$), where parallels diverge and triangle-angle sums fall below $\pi$; and elliptic geometry ($K>0$), where parallels converge and angle sums exceed $\pi$.

In all three classical models the curvature is constant, independent of position and direction. We explore a deliberately constructed metric that dramatizes a \emph{direction-dependent} split: near one coordinate axis it acts hyperbolically, near the perpendicular axis elliptically, with the two regimes separated by a sharp locus.

We work on $\R^2$ with global coordinates $(x,y)$ and metric coefficients
\[ E(y) = \sech^2 y = \frac{1}{\cosh^2 y}, \qquad G(x) = \cosh^2 x, \]
so that $ds^2 = E(y)\,dx^2 + G(x)\,dy^2$. The horizontal coefficient $E \le 1$ decays away from the $x$-axis (an expanding, hyperbolic-flavored direction); the vertical coefficient $G \ge 1$ grows away from the $y$-axis (a contracting, elliptic-flavored direction).

\section{Definitions}

Throughout, $\cosh t = \tfrac12(e^t + e^{-t})$ is even, satisfies $\cosh t \ge 1$ with equality iff $t=0$, and is strictly increasing on $[0,\infty)$.

\begin{definition}[Hyperbolic secant squared]
For $t\in\R$, $\ \sech^2 t := 1/\cosh^2 t.$
\end{definition}

\begin{definition}[Split metric]
The \emph{split metric} on $\R^2$ has coefficient functions $E(y)=\sech^2 y$ and $G(x)=\cosh^2 x$, acting on a tangent vector $(u,v)$ at $(x,y)$ by
\[ \|(u,v)\|^2_{(x,y)} = E(y)\,u^2 + G(x)\,v^2 . \]
\end{definition}

\begin{definition}[Sign-indicator curvature]
The \emph{sign-indicator curvature} is $K(x,y) := \sech^2 x - \sech^2 y.$
\end{definition}

\begin{definition}[Phase boundary and regions]
The \emph{phase boundary} is $\{K=0\}$. The \emph{elliptic region} is $\{|x|<|y|\}$; the \emph{hyperbolic region} is $\{|y|<|x|\}$.
\end{definition}

\section{Consistency: the metric is Riemannian}

\begin{lemma}[Positivity of the coefficients]\label{lem:pos}
For every $t$, $\sech^2 t > 0$; and for every $x$, $\cosh^2 x > 0$.
\end{lemma}
\begin{proof}
Since $\cosh t \ge 1 > 0$, both $\cosh^2 t$ and its reciprocal $\sech^2 t$ are strictly positive.
\end{proof}

\begin{theorem}[Consistency / positive-definiteness]\label{thm:posdef}
For every $(x,y)$ and every $(u,v)\ne(0,0)$,
\[ E(y)\,u^2 + G(x)\,v^2 > 0. \]
Hence the split metric is a positive-definite Riemannian metric, and its determinant $E(y)G(x) = \sech^2 y\cdot\cosh^2 x$ is strictly positive everywhere.
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:pos}, $E(y)>0$ and $G(x)>0$. If $u\ne0$ then $u^2>0$, so $E(y)u^2>0$; adding $G(x)v^2\ge0$ keeps the sum positive. The case $v\ne0$ is symmetric. The determinant is a product of positive numbers.
\end{proof}

The Riemannian area element is $\sqrt{EG}\,dx\,dy = \dfrac{\cosh x}{\cosh y}\,dx\,dy$, a positive density used in Section~\ref{sec:area}.

\section{The monotonicity engine}

\begin{theorem}[Monotonicity of $\sech^2$ in $|t|$]\label{thm:mono}
For all real $a,b$:
\begin{align*}
\text{(i)}\ & \sech^2 a < \sech^2 b \iff |b| < |a|; \\
\text{(ii)}\ & \sech^2 a \le \sech^2 b \iff |b| \le |a|; \\
\text{(iii)}\ & \sech^2 a = \sech^2 b \iff |a| = |b|.
\end{align*}
\end{theorem}
\begin{proof}
$\cosh$ is even and strictly increasing in $|t|$, so $\cosh a < \cosh b \iff |a|<|b|$. Since $\cosh a,\cosh b \ge 1>0$, squaring preserves this. Taking reciprocals reverses it:
\[ \sech^2 a < \sech^2 b \iff \cosh^2 b < \cosh^2 a \iff |b|<|a|, \]
giving (i). Statement (ii) is the negation of (i) with roles swapped, and (iii) follows from (ii) both ways with antisymmetry of $\le$.
\end{proof}

Thus $\sech^2$ is a strictly decreasing, faithful readout of \emph{magnitude}: blind to sign, exact on size.

\section{The phase boundary and the sign of curvature}

\begin{theorem}[Phase boundary equals the diagonals]\label{thm:boundary}
For $(x,y)\in\R^2$,
\[ K(x,y)=0 \iff \sech^2 x = \sech^2 y \iff |x|=|y| \iff x^2=y^2 \iff (x=y \text{ or } x=-y). \]
In particular the phase boundary is exactly the union of the diagonals $y=x$ and $y=-x$.
\end{theorem}
\begin{proof}
$K(x,y)=0$ iff $\sech^2 x = \sech^2 y$, which by Theorem~\ref{thm:mono}(iii) is $|x|=|y|$. As both sides are nonnegative, $|x|=|y|\iff x^2=y^2$, and $x^2-y^2=(x-y)(x+y)=0$ iff $x=y$ or $x=-y$.
\end{proof}

\begin{theorem}[Sign structure and trichotomy]\label{thm:sign}
For every $(x,y)$ exactly one holds:
\[ \begin{cases} K(x,y)>0 \text{ and } |x|<|y| & (\text{elliptic}),\\ K(x,y)=0 \text{ and } |x|=|y| & (\text{boundary}),\\ K(x,y)<0 \text{ and } |y|<|x| & (\text{hyperbolic}). \end{cases} \]
\end{theorem}
\begin{proof}
Compare $|x|$ and $|y|$ by trichotomy. If $|x|<|y|$, Theorem~\ref{thm:mono}(i) with $a=y,b=x$ gives $\sech^2 y<\sech^2 x$, so $K>0$. If $|x|=|y|$, Theorem~\ref{thm:boundary} gives $K=0$. If $|y|<|x|$, Theorem~\ref{thm:mono}(i) with $a=x,b=y$ gives $\sech^2 x<\sech^2 y$, so $K<0$. The three cases are exclusive and exhaustive.
\end{proof}

The diagonals partition the plane into four open wedges: the top and bottom wedges ($|x|<|y|$) are elliptic; the left and right wedges ($|y|<|x|$) are hyperbolic. Curvature sign alternates around the origin in a pinwheel pattern.

\section{Crossing the phase boundary at most twice}

\begin{theorem}[Crossing rigidity]\label{thm:crossing}
Let $\gamma(t)=(x_0+ta,\ y_0+tb)$ be a straight coordinate line with $a^2\ne b^2$. Then $\gamma$ meets the phase boundary in at most two distinct points; equivalently, among any three parameters $t_1,t_2,t_3$ with $\gamma(t_i)$ on the boundary, two coincide.
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:boundary}, $\gamma(t)$ is on the boundary iff $(x_0+ta)^2=(y_0+tb)^2$, i.e.
\begin{equation}\label{eq:quad}
(a^2-b^2)\,t^2 + 2(x_0a-y_0b)\,t + (x_0^2-y_0^2)=0.
\end{equation}
Since $a^2-b^2\ne0$, \eqref{eq:quad} is a genuine quadratic with at most two roots. Concretely, subtracting the equations for $t_1,t_2$ and factoring gives
\[ (t_1-t_2)\big[(a^2-b^2)(t_1+t_2)+2(x_0a-y_0b)\big]=0, \]
and likewise for $(t_1,t_3)$. If all three $t_i$ were distinct, the brackets vanish, yielding $(a^2-b^2)(t_1+t_2)=(a^2-b^2)(t_1+t_3)$, hence $(a^2-b^2)(t_2-t_3)=0$; as $a^2-b^2\ne0$ this forces $t_2=t_3$, a contradiction.
\end{proof}

\begin{remark}
The bound is sharp and is an instance of the classical fact that a line meets a conic in at most two points; here the conic is the degenerate pair $x^2=y^2$. Lines with $a^2=b^2$ (parallel to a diagonal) are excluded: they may lie on a diagonal or avoid the boundary entirely.
\end{remark}

\section{The split triangle and its area}\label{sec:area}

With area density $\sqrt{EG}=\cosh x/\cosh y$, the metric area of a coordinate region $R$ is
\[ \operatorname{Area}(R)=\iint_R \frac{\cosh x}{\cosh y}\,dx\,dy. \]
Since $\int\cosh x\,dx=\sinh x$ and $\int\sech y\,dy=\gd(y)$ with $\gd(y)=2\arctan(e^y)-\pi/2$ the Gudermannian, an axis-aligned rectangle $[x_1,x_2]\times[y_1,y_2]$ has area
\[ \big(\sinh x_2-\sinh x_1\big)\big(\gd(y_2)-\gd(y_1)\big). \]
For a triangle with one vertex in each phase the area is obtained by numerical quadrature of the same density. The anisotropy (largest along the $x$-axis, smallest along the $y$-axis) matches the curvature picture.

\section{Discussion: sign-indicator versus true curvature}

The function $K(x,y)=\sech^2 x-\sech^2 y$ is the \emph{sign-indicator} proposed for the geometry, chosen for its transparent diagonal phase structure; all theorems of Sections~5--6 are rigorous statements about it. It is \emph{not} the genuine Gaussian curvature. For an orthogonal metric $ds^2=E\,dx^2+G\,dy^2$, the Brioschi/Liouville formula gives
\[ K_{\mathrm{Gauss}}=-\frac{1}{2\sqrt{EG}}\left[\partial_x\!\left(\frac{G_x}{\sqrt{EG}}\right)+\partial_y\!\left(\frac{E_y}{\sqrt{EG}}\right)\right], \]
which for $E=\sech^2 y$, $G=\cosh^2 x$ evaluates to
\[ K_{\mathrm{Gauss}}(x,y)=-\cosh^2 y+\sech^2 x\,(2\sech^2 y-1), \]
agreeing with $K$ only at the origin and lacking the clean diagonal structure. What survives, fully proved, is the geometric skeleton: the comparison of $|x|$ with $|y|$ splits the plane along its diagonals into regions of opposite indicator sign, the metric is genuinely Riemannian, and straight coordinate lines cross the seam at most twice.

\section{Future directions}

\begin{enumerate}
\item \textbf{Derive the true Gaussian curvature in closed form.} Work out the Brioschi formula with differentiable coefficients and verify $K_{\mathrm{Gauss}}(x,y)=-\cosh^2 y+\sech^2 x(2\sech^2 y-1)$ and its sign set.
\item \textbf{Realize the conjectured $K$.} Seek, or rule out, an orthogonal/conformal metric with genuine Gaussian curvature $\sech^2 x-\sech^2 y$, via the Liouville equation $\Delta(\log\lambda)=-K\lambda$.
\item \textbf{Genuine geodesics.} Prove the ``at most two crossings'' bound for solutions of the geodesic equations via a Sturm/convexity argument.
\item \textbf{Split triangles and Gauss--Bonnet.} Compute the metric area $\iint \cosh x/\cosh y\,dx\,dy$ of a triangle with one vertex in each phase and relate it to $\iint K_{\mathrm{Gauss}}\,dA$.
\end{enumerate}

\section{Conclusion}

A single elementary inequality --- that $\sech^2 t$ strictly decreases in $|t|$ --- organizes a two-dimensional world into alternating regions of opposite curvature sign, separated by the diagonals $y=\pm x$, with straight paths crossing that seam at most twice. The metric is provably consistent, the phase structure exact, and the crossing bound a clean corollary of the quadratic.

\end{document}

