import math
from typing import List, Tuple

def sech2(t: float) -> float:
    """sech^2(t) = 1/cosh^2(t), the horizontal metric coefficient."""
    return 1.0 / math.cosh(t) ** 2

def metric_norm_sq(x: float, y: float, u: float, v: float) -> float:
    """Squared split-metric length of tangent vector (u,v) at (x,y)."""
    return sech2(y) * u ** 2 + math.cosh(x) ** 2 * v ** 2

def demo() -> None:
    samples: List[Tuple[float, float, float, float]] = [
        (0.0, 0.0, 1.0, 0.0), (2.0, -1.5, 0.0, 1.0),
        (-3.0, 2.0, 1.0, -1.0), (5.0, 5.0, 0.3, -0.7),
    ]
    for x, y, u, v in samples:
        val = metric_norm_sq(x, y, u, v)
        assert val > 0.0
        print(f"(x,y)=({x:+.1f},{y:+.1f}) v=({u:+.1f},{v:+.1f}): |v|^2={val:.6f} > 0")

if __name__ == "__main__":
    demo()

import math
from typing import List, Tuple

def sech2(t: float) -> float:
    return 1.0 / math.cosh(t) ** 2

def K(x: float, y: float) -> float:
    """Sign-indicator curvature K(x,y)=sech^2(x)-sech^2(y)."""
    return sech2(x) - sech2(y)

def phase(x: float, y: float, tol: float = 1e-12) -> str:
    k = K(x, y)
    if abs(k) <= tol:
        return "boundary"
    return "elliptic" if k > 0 else "hyperbolic"

def demo() -> None:
    pts: List[Tuple[float, float]] = [
        (0.0, 2.0), (2.0, 0.0), (3.0, 3.0), (2.0, -2.0), (1.0, 4.0), (4.0, -1.0)]
    for x, y in pts:
        # verify K sign matches magnitude comparison
        if abs(x) < abs(y):
            assert K(x, y) > 0
        elif abs(x) > abs(y):
            assert K(x, y) < 0
        else:
            assert abs(K(x, y)) < 1e-12
        print(f"(x,y)=({x:+.1f},{y:+.1f}): K={K(x,y):+.6f} -> {phase(x,y)}")

if __name__ == "__main__":
    demo()

import math
from typing import List

def boundary_crossings(a: float, b: float, x0: float, y0: float) -> List[float]:
    """Parameters t where the line (x0+ta, y0+tb) hits x^2=y^2, i.e. the roots
    of (a^2-b^2)t^2 + 2(x0 a - y0 b)t + (x0^2 - y0^2). At most two if a^2!=b^2."""
    A, B, C = a*a - b*b, 2.0*(x0*a - y0*b), x0*x0 - y0*y0
    if abs(A) < 1e-15:
        return [] if abs(B) < 1e-15 else [-C / B]
    disc = B*B - 4.0*A*C
    if disc < 0:
        return []
    s = math.sqrt(disc)
    return sorted({(-B + s)/(2*A), (-B - s)/(2*A)})

def demo() -> None:
    for a, b, x0, y0 in [(1.0,0.3,-2.0,0.5), (0.5,2.0,1.0,-3.0), (2.0,0.0,0.0,1.0)]:
        ts = boundary_crossings(a, b, x0, y0)
        assert len(ts) <= 2  # crossing rigidity
        print(f"dir=({a:+.1f},{b:+.1f}) base=({x0:+.1f},{y0:+.1f}): "
              f"{len(ts)} crossings at {[round(t,4) for t in ts]}")

if __name__ == "__main__":
    demo()
